// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherCartel} from "../src/EtherCartel.sol";

contract InvMutTest is Test {
    EtherCartel c;
    function setUp() public { c = new EtherCartel(); }
    function testFuzz_property(address actor) public {
        vm.assume(actor != address(this));
        vm.startPrank(actor);
        (bool success, ) = address(c).call(abi.encodeWithSignature("DrugDealer()"));
        vm.stopPrank();
        if (success) {
            assertEq(c.ceoAddress(), actor);
        } else {
            assertNotEq(actor, 0x85abE8E3bed0d4891ba201Af1e212FE50bb65a26);
        }
    }
}
